import { Show, type Component } from "solid-js";

import { Layout } from "#core/ui/utilities/utilities-layout.js";

/** Props for rendering a unit icon with an overlapping civ flag ribbon. */
export interface UnitFlagProps {
	color: string;
	unitIcon?: string;
	civSymbol?: string;
	class?: string;
	iconClass?: string;
	bannerClass?: string;
}

/** Unit icon with white border and an overlapping civ flag ribbon underneath. */
export const UnitFlag: Component<UnitFlagProps> = (props) => (
	<div class={`z-0 relative flex flex-col items-center ${props.class ?? ""}`}>
		<Show when={props.unitIcon}>
			{(iconCss) => (
				<div
					class={`relative size-9 p-1 rounded-full border border-white flex items-center justify-center ${props.iconClass ?? ""}`}
					style={{ "background-color": "rgba(14, 16, 20, 1)" }}
				>
					<div
						class="size-7 bg-center bg-contain bg-no-repeat"
						style={{ "background-image": iconCss() }}
					/>
				</div>
			)}
		</Show>
		<Show when={props.civSymbol}>
			{(civCss) => (
				<div class={`-z-1 relative w-9 h-14 -mt-4 flex justify-center ${props.bannerClass ?? ""}`}>
					<div
						class="absolute inset-0"
						style={{
							"border-image-slice": "40 31 31 31 fill",
							"border-image-width": `${Layout.pixels(40)} ${Layout.pixels(31)} ${Layout.pixels(31)} ${Layout.pixels(31)}`,
							"border-image-source": "url(blp:hud_frontbanner)",
							// eslint-disable-next-line solid/style-prop
							"fxs-border-image-tint": props.color,
						}}
					/>
					<div
						class="absolute inset-0"
						style={{
							"border-image-source": "url('blp:hud_frontbanner_shadow')",
							"border-image-slice": "40 31 31 31 fill",
							"border-image-width": `${Layout.pixels(40)} ${Layout.pixels(31)} ${Layout.pixels(31)} ${Layout.pixels(31)}`,
						}}
					/>
					<div
						class="absolute inset-0"
						style={{
							"border-image-source": "url('blp:hud_frontbanner_overlay')",
							"border-image-slice": "1 31 29 31 fill",
							"border-image-width": `${Layout.pixels(1)} ${Layout.pixels(31)} ${Layout.pixels(29)} ${Layout.pixels(31)}`,
						}}
					/>
					<div
						class="bg-contain bg-center bg-no-repeat relative size-6 self-end mb-3"
						style={{ "background-image": civCss() }}
					/>
				</div>
			)}
		</Show>
	</div>
);
